alter table public.twiga_business_voice_configs add column if not exists sautikit_agent_id text, add column if not exists sautikit_model_id text not null default 'sautikit-flash', add column if not exists sautikit_voice_id text not null default 'Woman';
create table if not exists public.twiga_scheduled_calls (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, customer_name text not null default '', phone_number text not null, reason text not null, scheduled_at timestamptz not null, timezone text not null default 'Africa/Nairobi', consent_status text not null default 'unknown' check (consent_status in ('unknown','requested','opted_in','opted_out')), trigger_type text not null default 'manual' check (trigger_type in ('manual','timer','missed_call','appointment_reminder','follow_up','conditional')), trigger_conditions jsonb not null default '{}'::jsonb, source_call_id uuid references public.twiga_call_records(id) on delete set null, calling_window_start time not null default '08:00', calling_window_end time not null default '20:00', voice_model_id text, voice_id text, status text not null default 'scheduled' check (status in ('scheduled','processing','submitted','completed','failed','cancelled','skipped','waiting_for_provider')), attempt_count integer not null default 0 check (attempt_count >= 0), max_attempts integer not null default 1 check (max_attempts between 1 and 5), retry_interval_minutes integer not null default 30 check (retry_interval_minutes between 5 and 1440), provider_call_id text, last_error text, last_attempt_at timestamptz, completed_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_by uuid default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists twiga_scheduled_calls_due_idx on public.twiga_scheduled_calls(status,scheduled_at) where status='scheduled';
create index if not exists twiga_scheduled_calls_business_idx on public.twiga_scheduled_calls(business_id,scheduled_at desc);
alter table public.twiga_scheduled_calls enable row level security;
drop policy if exists twiga_scheduled_calls_member_read on public.twiga_scheduled_calls; create policy twiga_scheduled_calls_member_read on public.twiga_scheduled_calls for select to authenticated using(public.is_member(business_id));
drop policy if exists twiga_scheduled_calls_member_insert on public.twiga_scheduled_calls; create policy twiga_scheduled_calls_member_insert on public.twiga_scheduled_calls for insert to authenticated with check(public.is_member(business_id) and (created_by is null or created_by=auth.uid()) and consent_status in ('requested','opted_in'));
drop policy if exists twiga_scheduled_calls_member_update on public.twiga_scheduled_calls; create policy twiga_scheduled_calls_member_update on public.twiga_scheduled_calls for update to authenticated using(public.is_member(business_id)) with check(public.is_member(business_id));
drop policy if exists twiga_scheduled_calls_owner_delete on public.twiga_scheduled_calls; create policy twiga_scheduled_calls_owner_delete on public.twiga_scheduled_calls for delete to authenticated using(exists(select 1 from public.business_members m where m.business_id=twiga_scheduled_calls.business_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
grant select,insert,update,delete on public.twiga_scheduled_calls to authenticated;
create or replace function public.twiga_claim_scheduled_calls(p_limit integer default 10) returns setof public.twiga_scheduled_calls language plpgsql security definer set search_path=public,pg_temp as $$ begin return query with due as (select id from public.twiga_scheduled_calls where status='scheduled' and scheduled_at<=now() and consent_status in ('requested','opted_in') and attempt_count<max_attempts order by scheduled_at asc for update skip locked limit greatest(1,least(coalesce(p_limit,10),50))) update public.twiga_scheduled_calls s set status='processing',attempt_count=s.attempt_count+1,last_attempt_at=now(),updated_at=now() from due where s.id=due.id returning s.*; end; $$;
revoke all on function public.twiga_claim_scheduled_calls(integer) from public,anon,authenticated; grant execute on function public.twiga_claim_scheduled_calls(integer) to service_role;
